
/* ── CV Download (embedded PDF) ── */
const RESUME_B64 = "";

function downloadCV() {
  const link = document.createElement('a');
  link.href = 'data:application/pdf;base64,' + RESUME_B64;
  link.download = 'Dileesha_Lakshan_CV.pdf';
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
}

['cvDownload','cvDownloadAbout','cvDownloadMob'].forEach(id => {
  const el = document.getElementById(id);
  if(el) el.addEventListener('click', e => { e.preventDefault(); downloadCV(); });
});

/* ── Sticky nav shadow ── */
const nav = document.getElementById('mainNav');
window.addEventListener('scroll', () => {
  nav.classList.toggle('scrolled', window.scrollY > 20);
});

/* ── Active nav link on scroll ── */
const sections = document.querySelectorAll('section[id]');
const navLinks = document.querySelectorAll('.nav-links a');
const observer = new IntersectionObserver(entries => {
  entries.forEach(e => {
    if(e.isIntersecting) {
      navLinks.forEach(a => {
        a.classList.toggle('active', a.getAttribute('href') === '#' + e.target.id);
      });
    }
  });
}, { threshold: 0.4 });
sections.forEach(s => observer.observe(s));

/* ── Hamburger / mobile menu ── */
const hamburger = document.getElementById('hamburger');
const mobileMenu = document.getElementById('mobileMenu');
hamburger.addEventListener('click', () => {
  hamburger.classList.toggle('open');
  mobileMenu.classList.toggle('open');
});
document.querySelectorAll('.mob-link').forEach(a => {
  a.addEventListener('click', () => {
    hamburger.classList.remove('open');
    mobileMenu.classList.remove('open');
  });
});

/* ── Smooth scroll ── */
document.querySelectorAll('a[href^="#"]').forEach(a => {
  a.addEventListener('click', e => {
    const target = document.querySelector(a.getAttribute('href'));
    if(target) { e.preventDefault(); target.scrollIntoView({behavior:'smooth'}); }
  });
});

/* ── Scroll reveal ── */
const revealObs = new IntersectionObserver(entries => {
  entries.forEach(e => { if(e.isIntersecting) e.target.classList.add('visible'); });
}, { threshold: 0.12 });
document.querySelectorAll('.reveal').forEach(el => revealObs.observe(el));

/* ── Skills tabs ── */
const tabs = document.querySelectorAll('.skill-tab');
const panels = document.querySelectorAll('.skills-panel');
tabs.forEach(tab => {
  tab.addEventListener('click', () => {
    tabs.forEach(t => { t.classList.remove('active'); t.setAttribute('aria-selected','false'); });
    panels.forEach(p => p.classList.remove('active'));
    tab.classList.add('active');
    tab.setAttribute('aria-selected','true');
    const panel = document.getElementById('panel-' + tab.dataset.panel);
    panel.classList.add('active');
    // animate skill bars
    panel.querySelectorAll('.s-fill').forEach(bar => {
      bar.style.width = '0%';
      setTimeout(() => { bar.style.width = bar.dataset.w + '%'; }, 80);
    });
  });
});
// init first panel bars
window.addEventListener('load', () => {
  document.querySelectorAll('#panel-data .s-fill').forEach(bar => {
    setTimeout(() => { bar.style.width = bar.dataset.w + '%'; }, 300);
  });
});

/* ── Contact form → mailto action ── */
const contactForm = document.getElementById('contactForm');
const submitBtn   = document.getElementById('submitBtn');
const submitText  = document.getElementById('submitText');
const formStatus  = document.getElementById('formStatus');

contactForm.addEventListener('submit', e => {
  e.preventDefault();
  const name    = document.getElementById('cf-name').value.trim();
  const email   = document.getElementById('cf-email').value.trim();
  const message = document.getElementById('cf-msg').value.trim();

  if(!name || !email || !message) {
    formStatus.className = 'form-status error';
    formStatus.textContent = 'Please fill in all fields before sending.';
    return;
  }
  const emailRe = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if(!emailRe.test(email)) {
    formStatus.className = 'form-status error';
    formStatus.textContent = 'Please enter a valid email address.';
    return;
  }

  submitBtn.disabled = true;
  submitText.textContent = 'Opening mail client…';

  const subject  = encodeURIComponent('Portfolio Enquiry from ' + name);
  const body     = encodeURIComponent('Hi Dileesha,\n\n' + message + '\n\nFrom: ' + name + '\nEmail: ' + email);
  const mailto   = 'mailto:dileeshalakshan2345@gmail.com?subject=' + subject + '&body=' + body;
  window.location.href = mailto;

  setTimeout(() => {
    formStatus.className = 'form-status success';
    formStatus.textContent = '✓ Your mail client should have opened. If not, email dileeshalakshan2345@gmail.com directly.';
    submitBtn.disabled = false;
    submitText.textContent = 'Send Message';
    contactForm.reset();
  }, 1500);
});
/* Animated Job Roles */
const roles = [
  "Data Analyst",
  "AI Builder",
  "Business Consultant",
  "Content Creator"
];

const roleElement = document.getElementById("animatedRole");

let roleIndex = 0;

setInterval(() => {
  roleElement.style.opacity = "0";
  roleElement.style.transform = "translateY(10px)";

  setTimeout(() => {
    roleIndex = (roleIndex + 1) % roles.length;
    roleElement.textContent = roles[roleIndex];

    roleElement.style.opacity = "1";
    roleElement.style.transform = "translateY(0)";
  }, 300);
}, 2500);
// Initialize EmailJS (make sure this runs after emailjs script is loaded)
document.addEventListener("DOMContentLoaded", () => {
    emailjs.init("1bo163HycOIpcJ-Oq");

    const form = document.getElementById("contactForm");
    const status = document.getElementById("formStatus");

    form.addEventListener("submit", function (e) {
        e.preventDefault();

        const params = {
            from_name: document.getElementById("cf-name").value,
            from_email: document.getElementById("cf-email").value,
            message: document.getElementById("cf-msg").value,
        };

        emailjs.send("service_knti4q3", "template_3n1efmh", params)
            .then((response) => {
                status.innerHTML = "✅ Message sent successfully!";
                form.reset();
                console.log("SUCCESS:", response);
            })
            .catch((error) => {
                status.innerHTML = "❌ Failed to send message. Check console.";
                console.error("EMAILJS ERROR:", error);
            });
    });
});